-- GRANT ALL PRIVILEGES ON SCHEMA `streamflix-lakehouse`.bronze TO `data-engineers`;
-- GRANT ALL PRIVILEGES ON SCHEMA `streamflix-lakehouse`.silver TO `data-engineers`;
-- GRANT ALL PRIVILEGES ON SCHEMA `streamflix-lakehouse`.gold TO `data-engineers`;
-- GRANT ALL PRIVILEGES ON SCHEMA `streamflix-lakehouse`.init_schema TO `data-engineers`;

-- BI Analysts - Read access to gold layer
-- GRANT USAGE ON CATALOG `streamflix-lakehouse` TO `bi-analysts`;
-- GRANT SELECT ON SCHEMA `streamflix-lakehouse`.gold TO `bi-analysts`;
-- GRANT SELECT ON TABLE `streamflix-lakehouse`.silver.audit_log TO `bi-analysts`;

-- Business Users - Read access to gold only
-- GRANT USAGE ON CATALOG `streamflix-lakehouse` TO `business-users`;
-- GRANT SELECT ON SCHEMA `streamflix-lakehouse`.gold TO `business-users`;

-- Data Scientists - Read silver/gold, write to gold
-- GRANT USAGE ON CATALOG `streamflix-lakehouse` TO `data-scientists`;
-- GRANT SELECT ON SCHEMA `streamflix-lakehouse`.silver TO `data-scientists`;
-- GRANT ALL PRIVILEGES ON SCHEMA `streamflix-lakehouse`.gold TO `data-scientists`;

-- ============================================================
-- 9. Verification Queries
-- ============================================================

-- Verify catalog
SELECT 'Catalog Verification' AS check_type,
       COUNT(*) AS schema_count
FROM system.information_schema.schemata
WHERE catalog_name = 'streamflix-lakehouse';

-- List all schemas
SHOW SCHEMAS IN `streamflix-lakehouse`;

-- List tables in each schema
SHOW TABLES IN `streamflix-lakehouse`.init_schema;
SHOW TABLES IN `streamflix-lakehouse`.silver;

-- List volumes
SHOW VOLUMES IN `streamflix-lakehouse`.bronze;
SHOW VOLUMES IN `streamflix-lakehouse`.silver;

-- Verify audit_log table structure
DESCRIBE EXTENDED `streamflix-lakehouse`.silver.audit_log;

-- Check quality rules inserted
SELECT * FROM `streamflix-lakehouse`.init_schema.quality_rules;

-- ============================================================
-- 10. Summary Report
-- ============================================================
SELECT
  'StreamFlix Lakehouse Initialization Complete' AS status,
  current_timestamp() AS completed_at,
  current_user() AS initialized_by;

-- End of initialization script
